"""Build original, portable examples and the authoritative v1 schema."""
import json
from pathlib import Path
S = {"type": "string"}
text = {"type": "string", "minLength": 1}
identifier = {"type":"string", "pattern":r"^[A-Za-z_][A-Za-z0-9_]*$"}
strings = {"type": "array", "items": S}
def obj(props, required=None):
    return {"type":"object", "additionalProperties":False, "properties":props, "required": list(props) if required is None else required}
def arr(items, minimum=0): return {"type":"array", "items":items, "minItems":minimum}
comparison = obj({"mode":{"enum":["exact","float","unordered"]}, "absoluteTolerance":{"type":"number","minimum":0}, "relativeTolerance":{"type":"number","minimum":0}}, ["mode"])
case = obj({"name":text,"input":{"type":"object"},"expected":{},"comparison":comparison}, ["name","input","expected"])
language = obj({"entrypoint":obj({"type":{"const":"function"},"name":identifier,"parameters":arr(obj({"name":identifier,"type":text})),"returns":text}),"starterCode":S})
schema = obj({"schemaVersion":{"const":"1.0.0"}, "id":{"type":"string","maxLength":128,"pattern":"^[a-z0-9]+([.-][a-z0-9]+)*$"}, "slug":{"type":"string","maxLength":100,"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$"},"title":text,"description":text,"difficulty":{"enum":["easy","medium","hard"]}, "organization":obj({"topic":text,"path":strings,"tags":strings,"companies":strings}), "constraints":strings,"examples":arr(obj({"input":{"type":"object"},"output":{},"explanation":S}),1),"languages":{"type":"object","minProperties":1,"propertyNames":{"pattern":"^[a-z][a-z0-9_-]*$"},"additionalProperties":language},"tests":obj({"public":arr(case,1),"hidden":arr(case)}),"comparison":comparison,"metadata":obj({"source":text,"author":text,"version":text})}, ["schemaVersion","id","slug","title","description","difficulty","organization","constraints","examples","languages","tests","metadata"])
schema.update({"$schema":"https://json-schema.org/draft/2020-12/schema", "$id":"https://lexor.dev/schemas/problem/v1.schema.json", "title":"Lexor Problem v1"})
Path('schemas/problem/v1.schema.json').write_text(json.dumps(schema,indent=2)+'\n')
def problem(folder, slug, title, description, difficulty, topic, tags, args, returns, cases, hidden, constraints):
    param = ', '.join(f'{k}: {v}' for k,v in args)
    fn = slug.replace('-','_')
    p = dict(schemaVersion='1.0.0', id=f'{folder}.{slug}',slug=slug,title=title,description=description,difficulty=difficulty,organization=dict(topic=topic,path=['Algorithms',topic],tags=tags,companies=[]),constraints=constraints,examples=[dict(input=c[0],output=c[1],explanation=c[2]) for c in cases],languages=dict(python=dict(entrypoint=dict(type='function',name=fn,parameters=[dict(name=k,type=v) for k,v in args],returns=returns),starterCode=f'def {fn}({param}) -> {returns}:\n    # Write your solution here.\n    pass\n')),tests=dict(public=[dict(name=f'Example {i+1}',input=c[0],expected=c[1]) for i,c in enumerate(cases)],hidden=[dict(name=f'Edge case {i+1}',input=c[0],expected=c[1]) for i,c in enumerate(hidden)]),metadata=dict(source='lexor-original',author='Lexor contributors',version='1.0.0'))
    Path(f'problems/{folder}/{slug}.json').write_text(json.dumps(p,indent=2)+'\n')
problem('arrays','two-sum','Two Sum','You are reconciling a list of transaction amounts. Find the two distinct positions whose values add up to the target. Return their zero-based indices in ascending order. There is exactly one matching pair. You may not use the same position twice.','easy','Arrays',['array','hashmap'], [('nums','list[int]'),('target','int')],'list[int]',[({'nums':[2,7,11,15],'target':9},[0,1],'The values at positions 0 and 1 add up to 9.'),({'nums':[3,2,4],'target':6},[1,2],'The values 2 and 4 form the matching pair.')],[({'nums':[3,3],'target':6},[0,1]),({'nums':[-1,0,4,7],'target':3},[0,2])],['2 ≤ len(nums) ≤ 10,000','Exactly one valid pair exists.','Return the smaller index first.'])
