problem('strings','valid-palindrome','Valid Palindrome','Normalize a phrase by keeping only alphanumeric characters and ignoring case. Decide whether the resulting sequence reads the same from left to right and right to left. An empty normalized sequence is a palindrome.','easy','Strings',['string','two-pointers'],[('s','str')],'bool',[({'s':'A man, a plan, a canal: Panama'},True,'Ignoring spaces and punctuation leaves a palindrome.'),({'s':'race a car'},False,'The normalized characters are not symmetric.')],[({'s':'!? '},True),({'s':'0P'},False)],['0 ≤ len(s) ≤ 100,000','Use Python str.isalnum() and str.lower() normalization.'])
problem('strings','longest-common-prefix','Longest Common Prefix','Find the longest beginning shared by every string in a collection. Return an empty string when the collection is empty or the strings do not share a first character.','easy','Strings',['string','trie'],[('strs','list[str]')],'str',[({'strs':['flower','flow','flight']},'fl','All three strings begin with fl.'),({'strs':['dog','racecar','car']},'','There is no shared prefix.')],[({'strs':[]},''),({'strs':['same','same']},'same'),({'strs':['','x']},'')],['0 ≤ len(strs) ≤ 200','Each string contains at most 200 characters.'])
